import { useEffect, useState } from 'react'
import { Save, Settings } from 'lucide-react'
import { settingsApi, type BusinessSettings, type Vendor } from '../../api'
import { Button } from '../../components/ui/button'
import { Card, CardContent } from '../../components/ui/card'
import { Input } from '../../components/ui/input'

const empty: BusinessSettings = { businessName: '', businessAddress: '', tin: '', vatRegistered: false, vatRate: 12, nearExpirationDays: 30, nearExpirationDiscountPercent: 0, receiptFooter: '', posPaymentMethods: ['CASH'], cameraScanningEnabled: true, receiptPrintMode: 'BROWSER' }
export function SettingsPage({ vendor }: { vendor?: Vendor }) { const [form, setForm] = useState<BusinessSettings>(empty); const [message, setMessage] = useState(''); useEffect(() => { if (vendor) settingsApi.get(vendor.id).then(setForm).catch(() => setForm(empty)) }, [vendor]); async function save() { if (!vendor) return; try { await settingsApi.update(vendor.id, form); setMessage('Business settings saved.') } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to save settings.') } } return <><div className="mb-6"><p className="text-[11px] font-bold uppercase tracking-[.17em] text-indigo-600">Business configuration</p><h1 className="mt-1.5 text-3xl font-black tracking-[-.055em]">Business settings</h1><p className="mt-2 text-[13px] text-slate-500">Configure tax, receipt, payment, scanning, and expiration preferences.</p></div>{message && <p className="mb-4 rounded-xl bg-emerald-50 p-3 text-sm font-semibold text-emerald-700">{message}</p>}<Card><CardContent className="p-5"><div className="grid gap-4 md:grid-cols-2"><label className="text-xs font-bold text-slate-600">Business name<Input value={form.businessName ?? ''} onChange={event => setForm({ ...form, businessName: event.target.value })} /></label><label className="text-xs font-bold text-slate-600">TIN<Input value={form.tin ?? ''} onChange={event => setForm({ ...form, tin: event.target.value })} /></label><label className="text-xs font-bold text-slate-600 md:col-span-2">Address<Input value={form.businessAddress ?? ''} onChange={event => setForm({ ...form, businessAddress: event.target.value })} /></label><label className="flex items-center gap-2 text-xs font-bold"><input type="checkbox" checked={form.vatRegistered} onChange={event => setForm({ ...form, vatRegistered: event.target.checked })} /> VAT registered</label><label className="text-xs font-bold text-slate-600">VAT rate<Input type="number" value={form.vatRate} onChange={event => setForm({ ...form, vatRate: Number(event.target.value) })} /></label><label className="text-xs font-bold text-slate-600">Near expiration days<Input type="number" value={form.nearExpirationDays} onChange={event => setForm({ ...form, nearExpirationDays: Number(event.target.value) })} /></label><label className="text-xs font-bold text-slate-600">Expiration discount %<Input type="number" value={form.nearExpirationDiscountPercent} onChange={event => setForm({ ...form, nearExpirationDiscountPercent: Number(event.target.value) })} /></label><label className="text-xs font-bold text-slate-600 md:col-span-2">Receipt footer<Input value={form.receiptFooter ?? ''} onChange={event => setForm({ ...form, receiptFooter: event.target.value })} /></label></div><Button className="mt-5" onClick={save}><Save size={16} /> Save settings</Button></CardContent></Card></> }
